import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Select from 'flarum/common/components/Select';
import isExtensionEnabled from 'flarum/admin/utils/isExtensionEnabled';
import textContrastClass from 'flarum/common/helpers/textContrastClass';
import classList from 'flarum/common/utils/classList';
import { decorateContent, heroDecoration } from '../../common/heroDecoration';
import { discussionChain, resolveConfig, tagParentId } from '../../common/resolveConfig';
import { DEFAULT_TEXT } from '../../common/types';
import { tagOrder, targetOf } from '../utils/scopes';
import { DEVICE_WIDTHS as WIDTHS } from '../utils/visibleArea';
const t = (key, params = {}) => app.translator.trans(`walsgit-custom-heroes.admin.preview.${key}`, params, true);

/**
 * A live preview of the edited hero, rendered like on the forum (same
 * classes, variables and container queries) at the real width of each device.
 */
export default class HeroPreview extends Component {
  device = 'desktop';
  /** Home (default level): preview the hero once Flarum's welcome text is closed. */
  closed = false;
  /** Discussions: the tag the sample discussion is in (preview only, not stored). */
  sampleTag = null;
  observer = null;
  onscroll = () => this.markStuck();
  view() {
    return m("div", {
      className: "wch-Preview"
    }, m("div", {
      className: "wch-Preview-toolbar"
    }, m("strong", {
      className: "wch-Preview-title"
    }, m(Icon, {
      name: "fas fa-eye"
    }), " ", t('title')), m("div", {
      className: "ButtonGroup"
    }, ['desktop', 'tablet', 'mobile'].map(device => m(Button, {
      className: classList('Button', this.device === device && 'active'),
      icon: {
        desktop: 'fas fa-desktop',
        tablet: 'fas fa-tablet-alt',
        mobile: 'fas fa-mobile-alt'
      }[device],
      "aria-pressed": this.device === device,
      onclick: () => this.device = device
    }, t(device)))), targetOf(this.attrs.target).scope === 'discussion' && this.sampleTagSelect(), targetOf(this.attrs.target).scope === 'global' && m("div", {
      className: "ButtonGroup"
    }, [false, true].map(closed => m(Button, {
      className: classList('Button', this.closed === closed && 'active'),
      "aria-pressed": this.closed === closed,
      onclick: () => this.closed = closed
    }, t(closed ? 'state_closed' : 'state_welcome'))))), m("div", {
      className: "wch-Preview-frame"
    }, m("div", {
      className: "wch-Preview-viewport",
      style: {
        width: `${WIDTHS[this.device]}px`
      }
    }, this.hero())), targetOf(this.attrs.target).scope === 'discussion' && isExtensionEnabled('flarum-tags') && m("p", {
      className: "helpText wch-Preview-note"
    }, m(Icon, {
      name: "fas fa-info-circle"
    }), " ", t('discussion_note')));
  }
  hero() {
    return previewHero(this.attrs, this.closed, this.sampleTag);
  }

  /** Every tag in Flarum's order, children indented: to see the hero with each tag's color. */
  sampleTagSelect() {
    const ids = isExtensionEnabled('flarum-tags') ? orderedTags().map(tag => tag.id) : [];
    if (!ids.length) return null;
    const options = Object.fromEntries(ids.map(id => {
      const tag = app.store.getById('tags', id);

      // Prefixed: numeric keys would be sorted by number, not in Flarum's order.
      return [`tag:${id}`, (tagParentId(tag) ? '\u00a0\u00a0└\u00a0' : '') + tag.attribute('name')];
    }));
    return m("label", {
      className: "wch-Preview-sampleTag"
    }, t('sample_tag'), m(Select, {
      value: `tag:${this.sampleTag ?? ids[0]}`,
      options: options,
      onchange: key => this.sampleTag = key.slice(4)
    }));
  }
  oncreate(vnode) {
    super.oncreate(vnode);

    // Scales the rendered width down to the frame, whatever the window size.
    this.observer = new ResizeObserver(() => this.fit());
    this.observer.observe(this.element.querySelector('.wch-Preview-frame'));
    window.addEventListener('scroll', this.onscroll, {
      passive: true
    });
    this.markStuck();
  }
  oninit(vnode) {
    super.oninit(vnode);
    this.closed = !!this.attrs.textTab;
  }
  onbeforeupdate(vnode) {
    // Compared before the new attrs replace the old ones.
    if (vnode.attrs.textTab && !this.attrs.textTab) this.closed = true;
    super.onbeforeupdate(vnode);
  }
  onupdate(vnode) {
    super.onupdate(vnode);
    this.fit();
  }
  onremove(vnode) {
    super.onremove(vnode);
    this.observer?.disconnect();
    window.removeEventListener('scroll', this.onscroll);
  }

  /** Adds a shadow while the preview is stuck at the top, like the admin header, to separate it from the forms. */
  markStuck() {
    const style = getComputedStyle(this.element);
    const top = parseFloat(style.top);
    // Not sticky on small screens.
    const stuck = style.position === 'sticky' && !isNaN(top) && this.element.getBoundingClientRect().top <= top + 1 && window.scrollY > 0;
    this.element.classList.toggle('wch-Preview--stuck', stuck);
  }
  fit() {
    const frame = this.element.querySelector('.wch-Preview-frame');
    const viewport = this.element.querySelector('.wch-Preview-viewport');
    if (frame && viewport) {
      // `zoom` rather than a transform: the layout box shrinks too, so the frame keeps the right height.
      viewport.style.zoom = String(Math.min(1, frame.clientWidth / WIDTHS[this.device]));
    }
  }
}

/**
 * The hero of a target, rendered like on the forum. Home (default level):
 * `closed` shows it once Flarum's welcome text is closed.
 */
export function previewHero({
  configs,
  target,
  chain
}, closed, sampleTag = null) {
  const {
    scope,
    scopeId
  } = targetOf(target);
  const payload = app.forum.attribute('walsgitCustomHeroes');
  const tag = scope === 'discussion' && isExtensionEnabled('flarum-tags') ? pickSampleTag(sampleTag) : undefined;
  // Like on the forum: the sample discussion can use the hero of its tag.
  if (scope === 'discussion') chain = discussionChain(configs, tag?.id, tag?.parentId);
  const decoration = heroDecoration(configs, chain, scope, payload.assetsUrl);
  const config = resolveConfig(configs, chain);
  // Like on the forum: without Flarum's welcome title, the hero is in its closed state.
  closed = scope === 'global' && (closed || !app.forum.attribute('welcomeTitle')?.trim());
  if (closed && (config.text ?? DEFAULT_TEXT).afterClose === 'none') {
    return m("p", {
      className: "wch-Preview-hidden"
    }, t('hidden'));
  }
  const content = heroContent(scope, scopeId, config, closed);
  // Flarum's deck hero can be closed too (for good, like in Flarum).
  const closable = scope === 'global' && !closed || scope === 'deck';
  if (scope === 'discussion') return discussionHero(config, decoration, tag);
  const children = [closable && m("i", {
    className: "Hero-close fas fa-times",
    "aria-hidden": "true"
  }), m("div", {
    className: "containerNarrow"
  }, content.title && m("h1", {
    className: "Hero-title"
  }, content.icon && m("i", {
    className: content.icon,
    "aria-hidden": "true"
  }), " ", content.title), content.subtitle !== null && (content.subtitle || content.title) && m("div", {
    className: classList('Hero-subtitle', closed && 'wch-Hero-message')
  }, content.subtitle))];
  const decorated = decoration ? decorateContent(children, decoration) : {
    content: children,
    corners: []
  };
  return m("header", {
    className: classList('Hero wch-PreviewHero', decoration?.className, content.color && 'wch-PreviewHero--colored'),
    style: {
      ...(content.color ? {
        '--hero-bg': content.color
      } : {}),
      ...decoration?.style
    }
  }, decoration?.background, m("div", {
    className: "container"
  }, decorated.content), decorated.corners);
}

/** The tags of the forum in Flarum's order: primary tags by position, each followed by its children, then secondary tags. */
function orderedTags() {
  const info = app.store.all('tags').map(tag => ({
    id: tag.id(),
    name: tag.attribute('name'),
    position: tag.attribute('position'),
    parentId: tagParentId(tag)
  }));
  return tagOrder(info).map(id => info.find(tag => tag.id === id));
}

/** The tag of the sample discussion: the chosen one, by default the first one. */
function pickSampleTag(id) {
  const tags = orderedTags();
  return tags.find(each => each.id === id) ?? tags[0];
}

/**
 * The tags of the sample discussion, like flarum/tags shows them: the chosen
 * tag (by default the first one), after its parent. The first one's color is
 * the hero's.
 */
function sampleTags(tag) {
  if (!tag) return [{
    name: t('tag_title'),
    color: ''
  }];
  const parent = orderedTags().find(each => each.id === tag.parentId);
  return [parent, tag].filter(each => !!each).map(each => ({
    name: each.name,
    color: app.store.getById('tags', each.id)?.attribute('color') || ''
  }));
}

/** A discussion hero, with Flarum's markup (sample tags, then the title), so that the forum styles apply. */
function discussionHero(config, decoration, tag) {
  const tagged = isExtensionEnabled('flarum-tags');
  const sample = tagged ? sampleTags(tag) : [];
  const tags = config.discussionTags === 'hidden' ? [] : sample;
  // flarum/tags colors the hero with its first tag.
  const color = config.tagColor === false ? '' : sample[0]?.color ?? '';
  const children = [m("ul", {
    className: "DiscussionHero-items"
  }, tags.length > 0 && m("li", {
    className: "item-tags"
  }, m("span", {
    className: "TagsLabel"
  }, tags.map(tag => m("span", {
    className: classList('TagLabel', tag.color && ['colored', textContrastClass(tag.color)]),
    style: tag.color ? {
      '--tag-bg': tag.color
    } : {}
  }, m("span", {
    className: "TagLabel-text"
  }, m("span", {
    className: "TagLabel-name"
  }, tag.name)))))), m("li", {
    className: "item-title"
  }, m("h1", {
    className: "DiscussionHero-title"
  }, t('discussion_title'))))];
  const decorated = decoration ? decorateContent(children, decoration) : {
    content: children,
    corners: []
  };
  return m("header", {
    className: classList('Hero DiscussionHero wch-PreviewHero', tagged && 'wch-PreviewHero--tagged', color && ['DiscussionHero--colored', textContrastClass(color)], decoration?.className),
    style: {
      ...(color ? {
        '--hero-bg': color
      } : {}),
      ...decoration?.style
    }
  }, decoration?.background, m("div", {
    className: "container"
  }, decorated.content), decorated.corners);
}

/** What the hero shows: the Welcome texts (default level), a tag, or a sample of the other heroes. */
function heroContent(scope, scopeId, config, closed) {
  if (scope === 'tag') {
    const tag = scopeId ? app.store.getById('tags', scopeId) : null;
    return tag ? {
      title: tag.attribute('name'),
      subtitle: config.tagDescription === false ? null : tag.attribute('description') || undefined,
      color: tag.attribute('color') || undefined,
      // Like Flarum: only when the tag has one.
      icon: config.tagIcon === false ? undefined : tag.attribute('icon') || undefined
    } : {
      title: t('tag_title'),
      subtitle: config.tagDescription === false ? null : t('tag_subtitle'),
      icon: config.tagIcon === false ? undefined : 'fas fa-tag'
    };
  }

  // Like Flarum's heroes of these extensions (their texts are not loaded in the admin).
  if (scope === 'messages' || scope === 'deck') {
    return {
      title: t(`${scope}_title`),
      subtitle: t(`${scope}_subtitle`),
      icon: scope === 'messages' ? 'fas fa-envelope' : 'fas fa-table-columns'
    };
  }
  if (closed) {
    const {
      title,
      message
    } = config.text ?? DEFAULT_TEXT;
    return {
      title: title.trim(),
      subtitle: message.trim() ? message : undefined
    };
  }

  // The Welcome message is HTML: the preview only needs its text.
  const message = new DOMParser().parseFromString(app.forum.attribute('welcomeMessage') ?? '', 'text/html').body.textContent ?? '';

  // Like on the forum: an empty core title or message is not shown.
  return {
    title: app.forum.attribute('welcomeTitle')?.trim() ?? '',
    subtitle: message.trim() || undefined
  };
}
flarum.reg.add('walsgit-custom-heroes', 'admin/components/HeroPreview', HeroPreview);